import sys; sys.path.insert(0, '/workspace/site/scripts/guides')
from ghelp import *
GUIDES = []
A = GUIDES.append

A(mk('facebook-two-factor-lost-access',
 'Can’t get your Facebook two-factor code? How to log in anyway',
 'Facebook Two-Factor Code Not Working? Log In Anyway',
 'Lost your phone or not receiving the Facebook login code? Approve from another device, use recovery codes or ask Facebook to confirm your identity.',
 'facebook', 'Two-factor', 'Facebook',
 'approve the login from a device where you’re already logged in, or use a saved recovery code. If you have neither, Facebook’s “Need another way to authenticate?” option starts an identity check.',
 'Facebook’s two-factor authentication blocks strangers, and it blocks you too when the phone with the codes is gone. The way back depends on what you can still reach, and on not making things worse by retrying blindly.',
 [('first', 'What to do first',
   '<p>Wait a few minutes before requesting another text. Carriers sometimes delay SMS, and repeat requests can leave you with several codes where only the latest works. While you wait, check these places:</p>'
   '<ul><li>A phone, tablet or computer where you’re <strong>still logged in</strong> to Facebook.</li><li>A printed or saved list of <strong>recovery codes</strong>.</li><li>An authentication app on another device.</li><li>A <strong>security key</strong> you registered.</li></ul>'),
  ('s1', 'Step 1: Approve the login from another device',
   '<p>If you’re logged in anywhere, check that device’s notifications. Facebook can show a prompt asking you to approve the new login. Approving from a device you already trust is the quickest fix and requires no code at all.</p>'),
  ('s2', 'Step 2: Use a recovery code',
   '<p>Recovery codes are one-time codes you could save when you set up two-factor authentication. Enter one on the code screen instead of an SMS or app code. Each works once, so cross it off. Once you’re in, generate a new set and store them somewhere other than the phone you use for codes.</p>'),
  ('s3', 'Step 3: Ask for more help',
   '<p>On the code screen choose <em>Need another way to authenticate?</em>, then <em>Other options</em> and <em>Get more help</em>. Follow the prompts. Facebook may ask for an ID, details about the account or a new contact method, then email you with next steps. Try it from a device and network you’ve used before, because Facebook weighs that signal.</p>'
   '<p>Meta doesn’t publish a timeline for these checks. Complete the request once and wait for the reply instead of starting a second one.</p>'),
  ('s4', 'Step 4: Fix it properly once you’re in',
   '<p>Once logged in you can turn two-factor authentication off, add a different authentication app, register a security key, or add a new phone number. Do at least two of these. The goal is that losing one device never locks you out again.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t rely on “trusted contacts.”</strong> Facebook has discontinued that feature, so any guide telling you to ask friends for codes is outdated.</li><li><strong>Don’t forward a code</strong> to anyone, even someone claiming to be Facebook support.</li><li><strong>Don’t create a duplicate profile</strong> and tell friends the old one is gone. It makes recovery and impersonation reports harder.</li><li><strong>Don’t pay for a “code workaround.”</strong> No outside party can change what Facebook asks for.</li></ul>'),
  ('after', 'Setting up a backup plan',
   '<p>Keep recovery codes in a password manager or a locked note, keep the phone number up to date, and register an authentication app on a second device where you can. If you travel often, keep an eye on roaming and SMS delivery before you leave.</p>')],
 [('Does Facebook have a way to skip the code?', 'Not for you to trigger. Facebook offers approval from another device, recovery codes and its identity check.'),
  ('Why is the SMS code not arriving?', 'Carrier delays, a full inbox, blocked short codes or a number that’s changed can all cause it. Wait, then check the number in settings once you’re in.'),
  ('How many recovery codes do I get?', 'Facebook provides a short list. Each works once, and you can generate a new list from the two-factor settings after login.'),
  ('Is asking Facebook for more help safe?', 'Yes, when you reach it through the official screens. Never share ID with a person who contacts you first.')],
 [('Facebook Help: Troubleshoot login with two-factor authentication', 'https://www.facebook.com/help/147926301947841'), ('Facebook Help: Account Recovery', 'https://www.facebook.com/help/292105707596942'), FB_HACKED, FB_HELP],
 [('/guides/hacked-facebook-account-recovery/', 'Hacked Facebook account recovery'), ('/guides/facebook-account-locked/', 'Facebook account locked'), ('/guides/facebook-lost-access-to-email-or-phone/', 'Lost your Facebook email or phone')],
 ['/guides/facebook-account-locked/', '/guides/hacked-facebook-account-recovery/'],
 'I can’t get my Facebook two-factor code and I’m locked out. Can you help?', 'Facebook two-factor lockout',
 ('Locked out by 2FA?', 'Tell us what you still have', 'Share what you can still reach, such as an old device or a recovery code. We’ll point you to the right official route.'),
 ('Still stuck?', 'We’ll walk it through with you', 'Message us the account name and the screen you’re on. We use official tools only and never ask for your password or codes.'),
 pill='Facebook two-factor lockout'))

A(mk('facebook-lost-access-to-email-or-phone',
 'Lost the email or phone linked to your Facebook account? Here’s the route back',
 'Lost Your Facebook Email or Phone? Get Back In',
 'No longer have the email or number on your Facebook account? Use the official identify page, a trusted device and Facebook’s identity check.',
 'facebook', 'Access', 'Facebook',
 'start at facebook.com/login/identify, search for your account, then choose the option for no longer having access. Use a device and network you’ve used with Facebook before.',
 'Old email addresses expire and phone numbers get recycled. When Facebook’s reset code goes to a place you can’t reach, you need another way to show the account is yours.',
 [('first', 'What to do first',
   '<p>Check whether you’re logged in anywhere. On a phone, tablet or browser with an active session you can add a new email and number in settings and the problem disappears. If you aren’t logged in anywhere, gather every address and number you may have used, and pick the device that’s most likely to be recognised: the one you used most for Facebook.</p>'),
  ('s1', 'Step 1: Search for your account',
   '<p>Go to facebook.com/login/identify and search with any email, phone number, username or name you used. When the account appears, choose the option that says you no longer have access to the listed contact details. If your account doesn’t appear, ask a friend to open your profile and copy the URL, because a profile username can help.</p>'),
  ('s2', 'Step 2: Give a new way to reach you',
   '<p>Facebook asks for a new email address or phone number where it can contact you. Use one that only you can access and that you’ll keep for months. This isn’t added to the account straight away; it’s where the next steps are sent.</p>'),
  ('s3', 'Step 3: Complete any identity check',
   '<p>Depending on the account, Facebook may ask you to identify friends in photos, upload an ID, or record a video selfie. Facebook’s help pages say to use a device and location you’ve logged in from before, and warn against switching devices mid-process. The ID rules are in our separate guide on Facebook ID requests.</p>'),
  ('s4', 'Step 4: Secure the account once you’re in',
   '<p>Add a fresh email and phone, remove outdated ones, change your password and check where you’re logged in. If two-factor authentication is on, save a new set of recovery codes and register an authentication app.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t open a new account</strong> and report the old one as fake. It can complicate recovery.</li><li><strong>Don’t give your login to someone who “can reset it for you.”</strong> They can’t, and it’s a common scam.</li><li><strong>Don’t repeatedly retry from different networks.</strong> It can look like suspicious activity.</li></ul>'),
  ('after', 'Avoiding it next time',
   '<p>Keep at least two contact methods on the account, and when you change your number or email provider, update Facebook the same week. If you manage a business Page, make sure at least one other full-control admin exists so the Page isn’t tied to one person’s mailbox.</p>')],
 [('Can I log in with my username instead?', 'Yes, if you know it. But you still need to pass the password and any two-factor step.'),
  ('What if my old number now belongs to someone else?', 'Remove it from the account once you’re back in. If you’re locked out, mention it in the recovery process.'),
  ('How long does the check take?', 'Meta doesn’t publish a timeline. Submit once and watch for an email.')],
 [('Facebook Help: Account Recovery', 'https://www.facebook.com/help/292105707596942'), ('Facebook: Find your account', 'https://www.facebook.com/login/identify'), FB_HACKED],
 [('/guides/hacked-facebook-account-recovery/', 'Hacked Facebook account recovery'), ('/guides/facebook-two-factor-lost-access/', 'Facebook two-factor lockout'), ('/guides/facebook-id-upload-request/', 'Facebook ID request')],
 ['/guides/hacked-facebook-account-recovery/'],
 'I lost access to the email and phone on my Facebook account and need help getting back in', 'Facebook email and phone access lost',
 ('No access to either?', 'Tell us what you have', 'Share your profile name and any email or number you may have used. We’ll point you to the right official step.'),
 ('Need help?', 'We’ll go through it with you', 'Message us the profile name and a screenshot of where you’re stuck. No passwords.'),
 pill='Facebook email or phone lost'))

A(mk('facebook-id-upload-request',
 'Facebook asked for ID: what’s accepted, how to upload and what to avoid',
 'Facebook Asked for ID? What’s Accepted & How',
 'Facebook asking you to confirm your identity with ID? Which documents work, how many you need, and how to avoid fake ID requests.',
 'facebook', 'Verification', 'Facebook',
 'upload only through Facebook’s own screen. One government ID with your name and either a date of birth or photo is accepted, or two non-government documents with your name.',
 'ID requests come up when you recover a locked account, appeal a decision or change a name. They’re legitimate when they appear inside Facebook. They’re also a scam favourite, so it pays to know the real rules.',
 [('first', 'What to do first',
   '<p>Check where the request appeared. A prompt on facebook.com or inside the app after logging in, or through an official recovery link, is fine. A message, DM or email telling you to upload ID “to avoid deletion” is not. If you can’t tell, close the message and log in directly.</p>'),
  ('s1', 'Step 1: Understand what’s accepted',
   '<p>Facebook’s help page says you can send one government-issued ID that shows your name and either your date of birth or your photo. If you don’t have one, two non-government documents showing your name are accepted, and at least one should include a photo or date of birth. The names should match each other and the account. Types vary by country, so check the live list on the help page.</p>'),
  ('s2', 'Step 2: Prepare clear images',
   '<ul><li>Use a bright, even light and a plain background.</li><li>Capture the whole document with all four corners visible.</li><li>Avoid glare on laminated surfaces and shadows over the text.</li><li>Use a current document, not one that has expired if the screen says current IDs only.</li><li>Don’t edit, filter or crop beyond what the screen asks.</li></ul>'),
  ('s3', 'Step 3: Upload and wait',
   '<p>Upload on the same device and network you used to start the process. Don’t close the page until it confirms. Facebook replies by email and inside the account. Meta doesn’t publish a timeline. The help page describes how ID images are protected and kept, so read the current wording to know what applies in your region.</p>'),
  ('s4', 'Step 4: If your name is a problem',
   '<p>If you use a nickname or a different form of your name, the documents have to support that name. Facebook’s name rules ask for the name you use in daily life, and our name-change guide explains what counts. If the account name and your ID differ widely, the check can fail.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t send ID to anyone who messages you.</strong> Facebook staff don’t ask for it by chat.</li><li><strong>Don’t use another person’s document</strong> or a doctored image.</li><li><strong>Don’t submit the same documents repeatedly</strong> if the first is pending.</li></ul>'),
  ('help', 'If your upload is rejected',
   '<p>Read the message for the reason. It’s often legibility, a mismatched name or a missing date. Try again once with a clearer photo or a different accepted document, and keep your explanation short and factual.</p>')],
 [('Does Facebook accept a passport?', 'Passports are generally accepted as government ID. Check the current list on the Help Center for your country.'),
  ('Can I upload ID from my phone?', 'Yes. A photo taken with the phone camera works if it’s sharp and shows the entire document.'),
  ('Is a scan of my ID safe?', 'Only if uploaded through Facebook’s official screen. Never send it to another person.')],
 [('Facebook Help: Types of IDs Facebook accepts', 'https://www.facebook.com/help/159096464162185'), ('Facebook Help: Names on Facebook', 'https://www.facebook.com/help/1090831264320592'), FB_HELP],
 [('/guides/facebook-account-disabled-appeal/', 'Facebook account disabled appeal'), ('/guides/facebook-name-change-rules/', 'Facebook name change rules'), ('/guides/facebook-lost-access-to-email-or-phone/', 'Lost your Facebook email or phone')],
 ['/guides/facebook-account-disabled-appeal/'],
 'Facebook asked me to upload ID and I want to check it is real before I submit', 'Facebook ID request',
 ('Not sure it’s real?', 'Send a screenshot', 'Send a screenshot of the request (not your ID) and we’ll tell you if it looks like the official flow.'),
 ('ID rejected?', 'We’ll help with the next step', 'Message us the profile name and the message you received. We use official routes and never ask for your login.'),
 pill='Facebook asked for ID'))

A(mk('facebook-name-change-rules',
 'Facebook name change: the 60-day limit and what names are allowed',
 'Facebook Name Change Rules: 60-Day Limit & Allowed Names',
 'How often you can change your Facebook name, what names are allowed, why a change may be refused and how to ask for a review with documents.',
 'facebook', 'Name', 'Facebook',
 'you can change your Facebook profile name once every 60 days, and it has to be the name you use in everyday life. A change can be refused if it breaks the naming rules.',
 'Name problems on Facebook usually come from one of three things: changing it too soon, using a format Facebook doesn’t allow, or being asked to prove the name you use.',
 [('first', 'What to do first',
   '<p>Check the date of your last change. If it was within 60 days, the option is blocked and you’ll have to wait. Also check what name you want against Facebook’s naming rules before you type it in, because a rejected request can start the wait too.</p>'),
  ('s1', 'Step 1: Know what’s allowed',
   '<p>Facebook asks for the name you use in daily life, so that friends can find you. Its rules say a name can’t include symbols, numbers, unusual capitalisation, repeated characters or punctuation, characters from multiple languages, titles of any kind such as professional or religious ones, words or phrases in place of a name, or offensive words. Nicknames are fine when they’re a variation on your real name, such as Bob for Robert.</p>'),
  ('s2', 'Step 2: Make the change',
   '<p>Open Settings, then Accounts Center, then <em>Profiles</em>, select your Facebook profile, and choose <em>Name</em>. Enter the first, middle and last name, review the preview, and save with your password. Facebook shows the date you’ll be allowed to change again.</p>'),
  ('s3', 'Step 3: If it’s refused or locked',
   '<p>Facebook’s help page lists reasons a name can’t be changed, such as a recent change, a name that doesn’t follow the rules, or a review in progress. If your real name is written in a way the system rejects, you can use Facebook’s contact form and attach up to three documents that show the name. Accepted documents are the same types used for ID checks.</p>'),
  ('s4', 'Step 4: Use a Page for brands',
   '<p>If you want a business name, a pen name or a brand identity, create a Facebook Page instead of putting it on your personal profile. A personal profile with a brand name can be asked to change it or be restricted.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t use a fake or celebrity name.</strong> It’s an impersonation risk.</li><li><strong>Don’t add titles, emojis or symbols</strong> to look unique.</li><li><strong>Don’t change your name repeatedly while an ID check is pending.</strong></li></ul>'),
  ('after', 'After a change',
   '<p>Update your Messenger and Instagram connections, tell close friends so they recognise the new name, and expect a short delay before everything shows consistently.</p>')],
 [('Why can’t I change my Facebook name?', 'Usually because you changed it in the last 60 days, the name breaks the rules, or Facebook has asked for ID.'),
  ('Can I use a nickname?', 'Yes, if it’s a variation of your real name, such as a shortened first name.'),
  ('Can I have a business name on my profile?', 'No. Use a Page for a business or brand.')],
 [('Facebook Help: Names on Facebook', 'https://www.facebook.com/help/1090831264320592'), ('Facebook Help: Reasons why you can’t change your name', 'https://www.facebook.com/help/448505685205813'), ('Facebook Help: Types of IDs accepted', 'https://www.facebook.com/help/159096464162185')],
 [('/guides/facebook-id-upload-request/', 'Facebook ID request'), ('/guides/facebook-account-disabled-appeal/', 'Facebook account disabled appeal'), ('/guides/facebook-page-restricted/', 'Facebook Page restricted')],
 ['/guides/facebook-account-disabled-appeal/'],
 'My Facebook name was flagged or I can’t change it and I want advice', 'Facebook name problem',
 ('Name flagged?', 'Ask us what to do', 'Tell us what Facebook said and we’ll tell you whether it’s a rules problem or a document problem.'),
 ('Account disabled over a name?', 'We’ll help with the appeal', 'Message us the profile name and the notice. We use official routes only.'),
 pill='Facebook name change rules'))

A(mk('facebook-deactivate-or-delete-account',
 'Deactivate or delete Facebook: what each does and what you lose',
 'Deactivate vs Delete Facebook: What You Lose',
 'Deactivating Facebook hides your profile and can be undone; deleting is permanent after a waiting period. What changes for Messenger, Pages and apps.',
 'facebook', 'Account', 'Facebook',
 'deactivate for a break (log in to reactivate). Delete only if you’re sure: permanent removal follows a 30-day window in which you can cancel.',
 'Deactivating and deleting sound alike but behave very differently. One keeps your data intact and your options open; the other doesn’t. Most regret comes from choosing deletion when a break was all that was needed.',
 [('first', 'What to do first',
   '<p>Download your information first, including photos, posts and messages. Then check three things that depend on your profile: Pages you manage, apps and sites where you log in with Facebook, and Messenger conversations you want to keep.</p>'),
  ('s1', 'Step 1: Deactivation',
   '<p>Deactivating is temporary. Your profile is hidden, but the posts and photos remain stored. You can reactivate by logging back in. Facebook says you can keep using Messenger while the profile is deactivated and friends can still message you.</p>'),
  ('s2', 'Step 2: Deletion',
   '<p>Deleting is permanent. After the cancellation window, your account and information are removed and can’t be recovered. Facebook says you can cancel by logging in and choosing <em>Cancel deletion</em> within 30 days, though the window can vary by region. Deletion also ends access to Messenger, though messages you sent may remain visible to others.</p>'),
  ('s3', 'Step 3: Where to do it',
   '<p>Open Settings, go to Accounts Center, then <em>Personal details</em> and <em>Account ownership and control</em>, and choose <em>Deactivation or deletion</em>. Select the profile and follow the prompts. Wording may differ slightly in your version.</p>'),
  ('s4', 'Step 4: Protect what depends on you',
   '<ul><li>Make another <strong>full-control admin</strong> on each Page before you leave, so it isn’t left without one.</li><li>Switch apps that use “Log in with Facebook” to email logins first.</li><li>Move important conversations and files out of Messenger.</li><li>Tell friends how to reach you.</li></ul>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t log in during the deletion window</strong> unless you want to cancel it.</li><li><strong>Don’t delete to escape a restriction.</strong> It doesn’t clear it and you can’t return.</li><li><strong>Don’t delete an account that is your only admin of a business Page.</strong></li></ul>'),
  ('after', 'If you change your mind',
   '<p>During deactivation or the deletion window, logging in restores things. After deletion completes, there’s no way back, so be certain you no longer need what’s in the account.</p>')],
 [('Does deactivating delete my posts?', 'No. They’re stored and become visible again if you reactivate.'),
  ('Will my Messenger still work?', 'It can if you deactivate and choose to keep Messenger. Deleting ends Messenger access.'),
  ('How do I cancel a deletion?', 'Log in within the window and select Cancel deletion.')],
 [('Facebook Help: Deactivating & deleting your account', 'https://en-gb.facebook.com/help/154908788002686'), ('Facebook Help: Permanently delete your account', 'https://www.facebook.com/help/224562897555674'), FB_HELP],
 [('/guides/facebook-account-disabled-appeal/', 'Facebook account disabled appeal'), ('/guides/facebook-page-admin-access-lost/', 'Lost access to a Facebook Page'), ('/facebook-account-suspended-180-days/', 'Facebook account suspended 180 days')],
 ['/facebook-account-suspended-180-days/'],
 'I’m not sure if my Facebook is deactivated, deleted or disabled and need help', 'Facebook deactivate or delete',
 ('Not sure which this is?', 'Tell us what you see', 'Describe the message and when it started and we’ll help you tell deactivated, deleted and disabled apart.'),
 ('Need to get it back?', 'We’ll check the route', 'Message us the profile name and what happened. We’ll tell you which official route fits.'),
 pill='Deactivate or delete Facebook'))

A(mk('facebook-memorialized-legacy-contact',
 'Facebook legacy contacts and memorialized accounts, explained',
 'Facebook Legacy Contact & Memorialized Accounts',
 'How Facebook memorialization works, what a legacy contact can and can’t do, how to set one up and how to request removal.',
 'facebook', 'Memorial', 'Facebook',
 'name a legacy contact in settings, or ask Facebook to memorialize a profile with proof of death. A legacy contact can’t log in or read messages.',
 'Facebook gives people two choices about their profile after death: leave it as a memorial, or have it deleted. Setting it up in advance spares your family a difficult process.',
 [('first', 'What to do first',
   '<p>If it’s your own account, set a legacy contact now. If you’re handling a loved one’s account, find out whether they chose a legacy contact or asked for deletion, and gather proof of death such as an obituary or news link.</p>'),
  ('s1', 'Step 1: Choose a legacy contact',
   '<p>Go to Settings, then Accounts Center, then <em>Personal details</em> and <em>Account ownership and control</em>, then <em>Memorialization</em>. You can choose a friend or family member, and you can allow them to download an archive of what you shared. You can also ask for your account to be deleted instead.</p>'),
  ('s2', 'Step 2: What a legacy contact can do',
   '<p>According to Facebook’s help pages, a legacy contact can pin a post on the memorial profile, update the profile and cover photos, respond to new friend requests, and download an archive if you allowed that. They can also ask for the account to be removed. They can’t log in as you, read your messages, remove friends or change past posts.</p>'),
  ('s3', 'Step 3: Request memorialization',
   '<p>Anyone can use Facebook’s memorialization request form with proof of death. Once approved, the word “Remembering” appears next to the name, and the profile’s existing content stays with the audience it was shared with. Memorializing also helps avoid birthday reminders and suggestions that can upset family.</p>'),
  ('s4', 'Step 4: Request removal',
   '<p>Verified immediate family or an authorised representative can ask Facebook to remove the account, with documents showing the relationship or authority. Read the form for what’s needed in your country.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t log in with a known password.</strong> It breaks Facebook’s terms and can lock the account.</li><li><strong>Don’t pay anyone</strong> who claims they can “unlock” a deceased person’s account.</li><li><strong>Don’t keep submitting forms.</strong> Meta doesn’t publish a timeline.</li></ul>')],
 [('Can a legacy contact post as me?', 'No. They can pin a tribute post and update photos, but they can’t log in or post as you.'),
  ('Can I change my legacy contact later?', 'Yes, in the same settings area, as long as you’re logged in.'),
  ('Is memorializing the same as deleting?', 'No. Memorialized profiles stay visible; deleted ones are removed.')],
 [('Facebook Help: Legacy contacts', 'https://www.facebook.com/help/991335594313139'), ('Facebook Help: What legacy contacts can do', 'https://www.facebook.com/help/625352257502955')],
 [('/guides/instagram-memorialized-account/', 'Instagram memorialized accounts'), ('/guides/facebook-deactivate-or-delete-account/', 'Deactivate or delete Facebook'), ('/guides/hacked-facebook-account-recovery/', 'Hacked Facebook account recovery')],
 ['/guides/hacked-facebook-account-recovery/'],
 'I need help with a deceased family member’s Facebook account', 'Facebook memorial request',
 ('Need guidance?', 'We can point you to the right form', 'Tell us the situation and we’ll help you choose between memorialization and removal.'),
 ('Need a hand?', 'We’ll help you prepare it', 'Message us. We’ll help you gather what the form needs and explain what to expect. No logins.'),
 pill='Facebook legacy contact'))

A(mk('facebook-suspicious-login-active-sessions',
 'Facebook says there was a login you don’t recognise: check and lock it down',
 'Unrecognised Facebook Login? Check Sessions & Lock Down',
 'See where you’re logged in on Facebook, end unknown sessions, turn on login alerts and spot signs of a takeover.',
 'facebook', 'Security', 'Facebook',
 'open Accounts Center, go to Password and security, tap Where you’re logged in, and log out of anything you don’t recognise. Then change your password.',
 'The “where you’re logged in” list is the most useful security screen on Facebook, and most people never open it. It shows every device that’s holding your account, with a time and rough location.',
 [('first', 'What to do first',
   '<p>Go to facebook.com directly instead of a link in an email or message. If you can still log in, work through the steps. If you can’t, use facebook.com/hacked and our hacked-account guide.</p>'),
  ('s1', 'Step 1: Open the sessions list',
   '<p>Go to Settings and privacy, then <em>Accounts Center</em>, then <em>Password and security</em>, then <em>Where you’re logged in</em>, and select your Facebook account. You’ll see each session with a date, time, location and device.</p>'),
  ('s2', 'Step 2: Judge what you see',
   '<p>An unfamiliar device or an unexpected country is a red flag. But locations are approximate and can reflect your mobile carrier’s network or a VPN, so look at the device type and time as well. If you’re unsure, log it out; you can always log back in on your own device.</p>'),
  ('s3', 'Step 3: End the sessions',
   '<p>Select an individual session and choose <em>Log out</em>, or select all and log out everywhere. You’ll need to log in again on your own devices. Then change your password to something unique, because ending a session doesn’t stop someone who already has it.</p>'),
  ('s4', 'Step 4: Add protections',
   '<ul><li>Turn on <strong>login alerts</strong> in Password and security.</li><li>Turn on <strong>two-factor authentication</strong> with an authentication app.</li><li>Run Facebook’s <strong>Security Checkup</strong> to review email, apps and recovery options.</li><li>Remove apps and websites you no longer use.</li></ul>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t click login-alert links in emails</strong> unless you opened them from a message you know is real.</li><li><strong>Don’t reuse a password</strong> from another site.</li><li><strong>Don’t forget your Pages.</strong> Check Page roles and linked ad accounts for changes.</li></ul>'),
  ('help', 'Signs the account is compromised',
   '<p>Posts you didn’t write, messages sent to friends, new Pages or ads, changed email or phone, or friend requests you didn’t send are all signs. Treat any of them as a takeover and follow the hacked-account steps.</p>')],
 [('Does an unknown location mean I was hacked?', 'Not always. Locations are estimates. Look at the device and time too.'),
  ('How do I log out of all devices?', 'In Where you’re logged in, select all sessions and choose Log out.'),
  ('Should I change my password?', 'Yes. Ending sessions doesn’t help if the attacker has your password.')],
 [('Facebook Help: Log out of Facebook on another device', 'https://www.facebook.com/help/174571515935086'), ('Facebook Help: Unfamiliar locations in Where you’re logged in', 'https://www.facebook.com/help/224047177607864'), FB_HACKED],
 [('/guides/hacked-facebook-account-recovery/', 'Hacked Facebook account recovery'), ('/guides/facebook-two-factor-lost-access/', 'Facebook two-factor lockout'), ('/guides/facebook-page-hacked-admin-removed/', 'Hacked Page, admin removed')],
 ['/guides/hacked-facebook-account-recovery/'],
 'I saw a login on my Facebook that I don’t recognise and want to secure the account', 'Facebook suspicious login',
 ('Not sure it’s safe?', 'Send us what you see', 'Share a screenshot of the sessions list and we’ll tell you what we’d do.'),
 ('Locked out already?', 'We’ll help you recover it', 'Message us the profile name and when you noticed. We use official routes only.'),
 pill='Facebook suspicious login'))

A(mk('facebook-support-inbox-violations',
 'How to check Facebook violations: Support Inbox, Account Status and Page Quality',
 'Check Facebook Violations: Support Inbox & Page Quality',
 'Where Facebook tells you about violations, how to find them for a profile or a Page, and how to request a review.',
 'facebook', 'Account status', 'Facebook',
 'open Help & Support, then Support Inbox. Page admins can also use Page Quality. Any item with a Request review button can be appealed from there.',
 'Facebook sends notices through several places, and people often miss them. Knowing where to look turns a vague “my reach is gone” into a specific, fixable item.',
 [('first', 'What to do first',
   '<p>Log in as the person who actually runs the profile or Page. For a Page, you need to be an admin. Open the app and tap your profile picture, then <em>Settings & privacy</em>, then <em>Help & support</em>, then <em>Support Inbox</em>.</p>'),
  ('s1', 'Step 1: Read the Support Inbox',
   '<p>The inbox lists messages about your content, your reports and enforcement actions, newest first. Open each one, note the policy cited and the date, and check what action was taken.</p>'),
  ('s2', 'Step 2: Check Page Quality',
   '<p>Admins can open Page Quality to see restrictions, removed content and violations for a Page. If a Page was unpublished or limited, this is where Facebook explains it. Our Page restrictions guide covers what each result means.</p>'),
  ('s3', 'Step 3: Request a review',
   '<p>If a notice shows <em>Request review</em>, choose it, follow the steps and submit once. For removed posts that don’t offer a button in the inbox, look for removed content under Account Status. Meta doesn’t publish a timeline, so expect the answer to appear in the same place.</p>'),
  ('s4', 'Step 4: Write down what happened',
   '<p>Screenshot each notice with the date. If a Page is restricted several times, a record shows whether the same type of content is involved and makes any later appeal clearer.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t delete the flagged post</strong> before you’ve appealed or saved a copy of the notice.</li><li><strong>Don’t appeal multiple times</strong> for the same item.</li><li><strong>Don’t ignore Support Inbox messages</strong> from a Page you share with others. Check with co-admins.</li></ul>')],
 [('Where is the Support Inbox?', 'In the Facebook app under Settings & privacy, then Help & support.'),
  ('Can editors see violations for a Page?', 'Typically admins with the right access see them. If you can’t, ask a full-control admin.'),
  ('Do violations expire?', 'Meta describes strikes expiring over time. See the strikes explanation for current details.')],
 [('Facebook Help: Find your Support Inbox', 'https://www.facebook.com/help/195906499396292'), ('Facebook Help: What to do if you don’t think content should have been removed', 'https://www.facebook.com/help/280908123309761')],
 [('/guides/facebook-page-restricted/', 'Facebook Page restricted'), ('/guides/facebook-account-disabled-appeal/', 'Facebook account disabled appeal'), ('/guides/instagram-check-account-status/', 'Instagram Account Status')],
 ['/guides/facebook-page-restricted/'],
 'I want help understanding a Facebook violation notice in my Support Inbox', 'Facebook violation notice',
 ('Confused by a notice?', 'Send us a screenshot', 'We’ll explain what it means and what we’d do next.'),
 ('Page restricted?', 'We’ll help plan the review', 'Message us the Page name and what Support Inbox shows. We use official routes only.'),
 pill='Check Facebook violations'))

A(mk('facebook-page-hacked-admin-removed',
 'Your Facebook Page was hacked and you were removed as admin',
 'Hacked Facebook Page & Removed as Admin: Steps',
 'What to do when someone takes over your Facebook Page and removes you: secure your profile, report the Page and use official dispute routes.',
 'facebook', 'Page hacked', 'Facebook',
 'secure your personal profile first, then use Facebook’s hacked Page steps and, if no admin access is possible, the Page Admin Dispute in Business Support Home.',
 'A Page takeover usually starts at the admin’s personal account or at a linked business portfolio. Fix that first, or the person who took the Page will take it again.',
 [('first', 'What to do first',
   '<p>Don’t start with the Page; start with <strong>you</strong>. Change your personal Facebook password, log out other sessions and check your email for notices. Hackers often take a Page by compromising an admin’s profile, so the profile is the open door.</p>'
   '<p>Take screenshots of the Page, its public posts and any ads. Note the date you lost access.</p>'),
  ('s1', 'Step 1: Check whether you still have any access',
   '<p>Look at the Page in your profile switcher, and in Meta Business Suite and any business portfolio. If you still have some role, you may be able to remove unknown admins, but only people with full control can make that change. Check linked Instagram accounts and ad accounts too.</p>'),
  ('s2', 'Step 2: Follow Facebook’s hacked Page steps',
   '<p>Facebook’s Help Center has a dedicated article for a hacked Page. It covers securing your account, removing unknown admins and reviewing recent activity. Work through it while you’re logged into your own profile on a device you’ve used before.</p>'),
  ('s3', 'Step 3: Use the Page Admin Dispute if you’re locked out',
   '<p>If you’ve been removed and no one can add you back, Meta’s Business Help Center has a Page Admin Dispute form reached through Business Support Home. It asks for identification, proof that you own or run the Page and a signed attestation. Gather these before you start, and be accurate; false documents end the request.</p>'),
  ('s4', 'Step 4: Contain the damage',
   '<ul><li>Check the linked <strong>ad account</strong> for charges you didn’t make and tell your bank or card provider about any.</li><li>Warn followers on another channel not to trust new offers from the Page.</li><li>Report scam posts or ads from the Page.</li><li>Check Instagram, WhatsApp and catalog links tied to the Page.</li></ul>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t pay a “Page recovery agent”</strong> who contacts you or hands you a Telegram contact. It’s a known scam pattern.</li><li><strong>Don’t create a copy Page</strong> with the same name, which can be reported as impersonation.</li><li><strong>Don’t keep logging in on a shared computer</strong> if it may be infected.</li></ul>')],
 [('How did the hacker remove me?', 'Usually via a compromised admin profile or an unsafe link. The first fix is securing every admin’s profile and email.'),
  ('How long does a Page admin dispute take?', 'Meta doesn’t publish a timeline. Submit once and watch for the email.'),
  ('Should I tell my customers?', 'Yes, through another channel, so they don’t fall for scams posted from the Page.')],
 [('Facebook Help: Hacked Page', 'https://www.facebook.com/help/738660629556925'), ('Meta Business Help: Submit a Page Admin Dispute', 'https://www.facebook.com/business/help/1580486349413648'), ('Meta Business Support Home', 'https://www.facebook.com/business/help/254088759757736')],
 [('/guides/hacked-facebook-account-recovery/', 'Hacked Facebook account recovery'), ('/guides/facebook-page-admin-access-lost/', 'Lost access to a Facebook Page'), ('/guides/meta-business-portfolio-restricted/', 'Business portfolio restricted')],
 ['/guides/hacked-facebook-account-recovery/', '/guides/facebook-page-restricted/'],
 'My Facebook Page was hacked and I was removed as admin and need help', 'Hacked Facebook Page',
 ('Page taken over?', 'Tell us what happened', 'Share the Page name and when you lost access. We’ll point you to the right official steps.'),
 ('Locked out of the Page?', 'We’ll help with the dispute', 'Message us the Page name and what you’ve tried. We use official routes only and never ask for passwords.'),
 pill='Hacked Facebook Page'))

A(mk('facebook-page-admin-access-lost',
 'Lost access to your Facebook Page because an admin left',
 'Lost Access to a Facebook Page? Admin Left or Unreachable',
 'An agency, employee or ex-partner controls your Facebook Page and you can’t get in. Ask for access, use the admin dispute and plan so it doesn’t repeat.',
 'facebook', 'Page access', 'Facebook',
 'ask a current or former admin to add you. If nobody can, submit a Page Admin Dispute through Business Support Home with ID and ownership proof.',
 'Not every lost Page is a hack. Often an agency, a former employee or a founder who moved on is the only full-control admin, and the business can’t reach its own audience.',
 [('first', 'What to do first',
   '<p>Find out <strong>who</strong> has access. Look at the Page publicly, ask staff, and check old emails for invitations. Contact a known admin politely and in writing, asking to be added with full control. Most of the time it ends here.</p>'),
  ('s1', 'Step 1: Ask for the right role',
   '<p>Only people with full control can add or remove admins. Ask for full control, not just editor access, and ask them to also check whether the Page sits inside a business portfolio. Roles inside a portfolio are managed in Meta Business Suite.</p>'),
  ('s2', 'Step 2: Request access through Facebook',
   '<p>Facebook’s help pages describe a way to request access to a Page. It sends the request to existing admins, who can approve it. It won’t succeed if no admin responds.</p>'),
  ('s3', 'Step 3: File the admin dispute',
   '<p>If the admin is gone or refuses, use the Page Admin Dispute in Business Support Home. Be ready with government ID, evidence the business owns the Page (registrations, invoices, domain records, past ad receipts) and a signed attestation. If the Page is linked to a business portfolio you also can’t reach, there is a separate request for full control of a portfolio.</p>'),
  ('s4', 'Step 4: Watch the clock',
   '<p>Facebook’s help page on Page access explains that a Page with no full-control admin can be deactivated and eventually removed. Don’t let it sit unresolved for months.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t threaten or harass the former admin.</strong> It can backfire in any dispute.</li><li><strong>Don’t build a new Page with the same name</strong> and split your audience before the dispute ends.</li><li><strong>Don’t fabricate documents.</strong></li></ul>'),
  ('after', 'Prevent it happening again',
   '<p>Keep at least two trusted people with full control, use a business portfolio owned by the business and not by an employee’s personal profile, and keep a record of who has which role. Review it whenever someone leaves.</p>')],
 [('Can Facebook add me to the Page for me?', 'Not on request alone. The official routes are admin approval or the dispute process.'),
  ('What proof of ownership works?', 'Business registration, invoices, domain records and other documents that link you to the business, as listed in the form.'),
  ('What if the Page is in an agency’s business portfolio?', 'Ask the agency to share or transfer it. If they won’t, the dispute process is the official route.')],
 [('Facebook Help: Request access to a Page', 'https://www.facebook.com/help/531084028683914'), ('Meta Business Help: Page Admin Dispute', 'https://www.facebook.com/business/help/1580486349413648'), ('Meta Business Help: Request full control of a business portfolio', 'https://www.facebook.com/business/help/474856681929983')],
 [('/guides/meta-business-portfolio-lost-admin-access/', 'Lost admin access to a business portfolio'), ('/guides/facebook-page-hacked-admin-removed/', 'Hacked Page, admin removed'), ('/guides/facebook-page-restricted/', 'Facebook Page restricted')],
 ['/guides/facebook-page-restricted/'],
 'I lost admin access to my Facebook Page and need to get it back', 'Facebook Page access lost',
 ('Locked out of your own Page?', 'Tell us the situation', 'Share the Page name and who has access. We’ll tell you which official route fits.'),
 ('Need help preparing it?', 'We’ll help you gather the proof', 'Message us. We’ll help you gather what the dispute form needs. No passwords.'),
 pill='Lost access to a Facebook Page'))

A(mk('facebook-marketplace-restricted',
 'Facebook Marketplace access limited or suspended: how to request review',
 'Facebook Marketplace Suspended or Limited? Review Steps',
 'What it means when Marketplace is at risk, limited or suspended, how to request a review from Profile status, and how to avoid repeat problems.',
 'facebook', 'Marketplace', 'Facebook',
 'in the Facebook app open your profile, tap Profile status, choose Marketplace, then Fix it now and Request review. Some warnings can be removed; removed listings stay removed.',
 'Marketplace restrictions are handled separately from your main account. You can lose selling rights and still use Facebook normally. The good news is there’s a built-in way to ask for a second look.',
 [('first', 'What to do first',
   '<p>Open Facebook on your phone, go to your profile and find <strong>Profile status</strong>. Under Extra features you’ll see Marketplace with one of three states: at risk, limited or suspended. Tap it, read what Facebook says and note the listing or behaviour behind it.</p>'),
  ('s1', 'Step 1: Understand the levels',
   '<p>“At risk” is a warning that rules were broken. “Limited” cuts some features. “Suspended” removes access. Facebook’s help page explains each and notes that the available action depends on the situation.</p>'),
  ('s2', 'Step 2: Request a review',
   '<p>Choose <em>Fix it now</em> and then <em>Request review</em> and follow the prompts. Facebook says a first-time warning may be removed if the review goes your way, though listings that caused the issue won’t be restored. Meta doesn’t publish a timeline.</p>'),
  ('s3', 'Step 3: If a single listing was rejected',
   '<p>Go to Profile status, Marketplace, and open the listing marked as rejected. Choose to request review. Facebook’s help page says review may be unavailable after 180 days, after a previous request, or for certain violations, so don’t wait.</p>'),
  ('s4', 'Step 4: Fix the cause',
   '<p>Common causes include prohibited items, duplicated listings, misleading photos or prices, listing items you don’t have, and complaints from buyers. Read Facebook’s commerce policies and adjust your listings. For repeat sellers, clear photos, honest descriptions and responsive messages reduce complaints.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t sell on a second account</strong> to get around a restriction. That can lead to bigger action.</li><li><strong>Don’t keep relisting a rejected item</strong> without changing what was wrong.</li><li><strong>Don’t take buyers off-platform to avoid rules</strong> or move payment to unsafe channels.</li></ul>')],
 [('Does a Marketplace suspension affect my Facebook?', 'Not directly. Your account and Pages can keep working.'),
  ('Will the removed listing return if I win the review?', 'No. Facebook says the listings that caused a warning are not restored.'),
  ('Can I appeal after 180 days?', 'Facebook’s help page says review may no longer be available after that.')],
 [('Facebook Help: Marketplace access at risk, limited or suspended', 'https://www.facebook.com/help/972392066266648'), ('Facebook Help: Marketplace listing rejected', 'https://www.facebook.com/help/2193854224216494'), ('Meta Commerce Policies', 'https://www.facebook.com/policies_center/commerce/')],
 [('/guides/facebook-support-inbox-violations/', 'Check Facebook violations'), ('/guides/facebook-account-disabled-appeal/', 'Facebook account disabled appeal'), ('/guides/facebook-page-restricted/', 'Facebook Page restricted')],
 ['/guides/facebook-account-disabled-appeal/'],
 'My Facebook Marketplace access is limited or suspended and I want to request a review', 'Facebook Marketplace restriction',
 ('Marketplace blocked?', 'Show us the message', 'Send a screenshot of Profile status and we’ll tell you what we’d do next.'),
 ('Need help?', 'We’ll plan the review with you', 'Message us the profile name and the message. We use official routes and never ask for logins.'),
 pill='Facebook Marketplace restricted'))

A(mk('report-scam-ad-or-fake-page-facebook',
 'How to report a scam ad or a fake business Page on Facebook',
 'Report a Scam Ad or Fake Page on Facebook',
 'The official way to report a scam ad, a Page pretending to be your business or a fraudulent seller on Facebook, and what to save before you do.',
 'facebook', 'Report', 'Facebook',
 'use the three-dot menu on the ad and choose Report ad. For a fake Page, open Options under the cover photo and choose Report Page. Save evidence first.',
 'Scam ads and cloned Pages hurt customers and your reputation. Reporting through Facebook’s official routes works best when you give specific, accurate information, and more reports don’t make a decision faster.',
 [('first', 'What to do first',
   '<p>Don’t click, reply or pay. Screenshot the ad or Page, copy the URL, and note the date and any payment method requested. If you’ve already paid, contact your bank or card provider right away; reports to Facebook don’t refund money.</p>'),
  ('s1', 'Step 1: Report the scam ad',
   '<p>On the ad, tap the three dots and choose <em>Report ad</em>, then choose the option for misleading or scam content and follow the prompts. Report each ad you see; they can differ even when the same advertiser runs them.</p>'),
  ('s2', 'Step 2: Report a Page pretending to be you or your business',
   '<p>Open the fake Page, tap or click the options below the cover photo, choose <em>Report Page</em> and select that it’s pretending to be someone or something else. Facebook’s help page gives separate steps for people and for businesses.</p>'),
  ('s3', 'Step 3: Use brand tools if you qualify',
   '<p>Businesses enrolled in Meta’s Brand Rights Protection can search and report scam ads and impersonation through that tool. Check whether your business is eligible in the Meta Business Help Center.</p>'),
  ('s4', 'Step 4: Warn people the right way',
   '<p>Post a clear notice on your genuine Page with your real contact details and website. Don’t name individuals or share the scammer’s personal information. Link to Facebook’s reporting page so customers can report too.</p>'),
  ('dont', 'What not to do',
   '<ul><li><strong>Don’t arrange mass reports from friends.</strong> Reports are assessed against the rules, not counted like votes.</li><li><strong>Don’t contact the scammer</strong> or pretend to buy.</li><li><strong>Don’t publish personal details</strong> about a suspected scammer.</li></ul>'),
  ('after', 'If it keeps coming back',
   '<p>Keep a log of each Page, URL and date. If new copies appear after you’ve reported one, repeat the process with the new URL and add the previous reports to your notes. Meta doesn’t publish a timeline for removals.</p>')],
 [('Will Facebook refund me for a scam?', 'No. Contact your payment provider and local fraud authorities.'),
  ('How do I report a fake Page of my business?', 'Use Report Page on the fake Page and choose that it’s pretending to be a business, or use Brand Rights Protection if eligible.'),
  ('Why is the scam ad still running?', 'Reports are assessed against the rules and not every report leads to removal. Report again with different ads and add detail.')],
 [('Facebook Help: Report a profile or Page pretending to be you or someone else', 'https://www.facebook.com/help/167722253287296'), ('Meta Scam Protection Center', 'https://www.meta.com/safety/scam-protection-center/'), FB_HELP],
 [('/guides/instagram-scam-dm-what-to-do/', 'Scam DM on Instagram'), ('/report-business-impersonation/', 'Report business impersonation'), ('/fake-account-takedown/', 'Fake account takedown')],
 ['/report-business-impersonation/', '/fake-account-takedown/'],
 'A fake Page is pretending to be my business and I want to report it properly', 'Fake Facebook Page report',
 ('Cloned Page?', 'Send us the links', 'Share the fake Page and your real one. We’ll help you report it properly. No passwords needed.'),
 ('Still running?', 'We’ll help build the report', 'Message us the links and what you’ve reported. We’ll help you put together a clear, accurate report.'),
 svc='ban', pill='Report a scam ad or fake Facebook Page'))
